"""Cuaderno del estudiante, 2.º medio Lengua y Literatura, OA 02 (experiencia humana y herencias culturales) y OA 03 (análisis de narraciones).

Todos los textos (poemas, fragmentos, relatos) son originales e inventados («de ejemplo»); cada ejercicio trae escritos los textos y datos que necesita.
Notas para el docente:
- Los títulos de las clases del repositorio son pasos generales (entrar, localizar, analizar, contrastar, situar, formular, revisar); este cuaderno los sigue
  y reparte entre ellos los contenidos del OA oficial (OA 02: dimensiones de la experiencia humana y herencias culturales; OA 03: conflicto, personajes,
  narrador, personajes tipo, símbolos y tópicos, creencias y prejuicios, recursos temporales e intertextualidad). En OA 03 la clase 6 enseña la arquitectura temporal
  y la 7 la intertextualidad.
- Las obras sugeridas por el currículo (plan lector) son obras reales: aquí la destreza se enseña con textos inventados; la lectura de las obras reales queda para el docente.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA2 = "LE2M OA 02"
OA3 = "LE2M OA 03"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


